// 从一个小小的问候开始
const alert = new Alert();
alert.title = "你好，Android 👋";
alert.message = "写下你的名字，开始你的脚本旅程。";
alert.addTextField("你的名字", "朋友");
alert.addAction("打个招呼");
alert.addCancelAction("下次再说");

const choice = await alert.presentAlert();
if (choice === 0) {
  const name = alert.textFieldValue(0) || "朋友";
  console.log("你好，" + name + "！");
  console.log("你的第一个 JavaScript 脚本运行成功。");
} else {
  console.log("随时欢迎回来。");
}

