// 写入与读取应用内的本地文件
const fm = FileManager.local();
const path = fm.joinPath(fm.documentsDirectory(), "my-note.txt");
const previous = fm.fileExists(path) ? fm.readString(path) : "";

const alert = new Alert();
alert.title = "随手记一笔";
alert.message = "内容会保存在这台设备的应用目录中。";
alert.addTextField("今天有什么想法？", previous);
alert.addAction("保存");
alert.addCancelAction("取消");

if (await alert.presentAlert() === 0) {
  const note = alert.textFieldValue(0);
  fm.writeString(path, note);
  console.log("保存成功：" + path);
  console.log(fm.readString(path));
} else {
  console.log("已取消，原来的笔记仍然保留。");
}

// 使用公开演示接口，需要网络连接
const request = new Request("https://jsonplaceholder.typicode.com/todos/1");
request.timeoutInterval = 15;

try {
  const todo = await request.loadJSON();
  console.log("HTTP 状态：" + request.response.statusCode);
  console.log("任务：" + todo.title);
  console.log("完成状态：" + (todo.completed ? "已完成" : "待完成"));
  await QuickLook.present(todo);
} catch (error) {
  console.error("请求失败：" + error.message);
  console.log("请确认手机可以访问该 HTTPS 接口，然后重试。");
}

// 剪贴板读取需要在前台运行；浏览器可能需要授权
const text = await Pasteboard.readString();
if (!text || !text.trim()) {
  console.log("剪贴板中没有文字。先复制一段文字再试试。");
} else {
  const cleaned = text.trim().replace(/\n{3,}/g, "\n\n");
  Pasteboard.copyString(cleaned);
  console.log("已整理并复制 " + cleaned.length + " 个字符。");
  console.log(cleaned);
}

